import{j as n,Z as r,b as e,c as s,ae as a,A as o,s as i,f as d,q as g,au as p}from"./chunks/framework.DkjvVb1g.js";const m=JSON.parse('{"title":"Agent 开发范式面试题","description":"Agent 后端开发常见范式，包括 ReAct、Plan-and-Execute、工具调用、记忆和多 Agent。","frontmatter":{"title":"Agent 开发范式面试题","description":"Agent 后端开发常见范式，包括 ReAct、Plan-and-Execute、工具调用、记忆和多 Agent。","date":"2026-06-11T00:00:00.000Z","tags":["Agent","Tool Calling","后端"],"categories":["面经"]},"headers":[],"relativePath":"interview/agent-backend/agent-patterns.md","filePath":"interview/agent-backend/agent-patterns.md","lastUpdated":1782271370000}'),h={name:"interview/agent-backend/agent-patterns.md"};function A(c,t,u,E,_,b){const l=r("Mermaid");return e(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781136000000"},[t[1]||(t[1]=a('<h1 id="agent-开发范式面试题" tabindex="-1">Agent 开发范式面试题 <a class="header-anchor" href="#agent-开发范式面试题" aria-label="Permalink to “Agent 开发范式面试题”">​</a></h1><h2 id="_1-什么是-agent" tabindex="-1">1. 什么是 Agent？ <a class="header-anchor" href="#_1-什么是-agent" aria-label="Permalink to “1. 什么是 Agent？”">​</a></h2><p>Agent 是以 LLM 为推理核心，能够感知上下文、规划任务、调用工具、观察结果并迭代完成目标的系统。</p><p>一个工程化 Agent 通常包含：</p><ul><li>LLM 推理层</li><li>Prompt/指令层</li><li>工具调用层</li><li>记忆/上下文层</li><li>状态机/工作流层</li><li>评测与观测层</li><li>权限与安全层</li></ul><h2 id="_2-react-范式是什么" tabindex="-1">2. ReAct 范式是什么？ <a class="header-anchor" href="#_2-react-范式是什么" aria-label="Permalink to “2. ReAct 范式是什么？”">​</a></h2><p>ReAct = Reasoning + Acting。</p><p>流程：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Thought -&gt; Action -&gt; Observation -&gt; Thought -&gt; Action -&gt; Observation -&gt; Final</span></span></code></pre></div><p>优点：</p><ul><li>适合需要多步推理和工具调用的问题。</li><li>每一步都能根据工具反馈修正策略。</li><li>可解释性较强。</li></ul><p>缺点：</p><ul><li>token 消耗高。</li><li>多轮调用延迟高。</li><li>如果没有约束，容易循环调用或调用错误工具。</li></ul><h2 id="_3-plan-and-execute-是什么" tabindex="-1">3. Plan-and-Execute 是什么？ <a class="header-anchor" href="#_3-plan-and-execute-是什么" aria-label="Permalink to “3. Plan-and-Execute 是什么？”">​</a></h2><p>先由规划器生成任务计划，再由执行器逐步执行。</p><p>适合场景：</p><ul><li>长任务</li><li>多工具协作</li><li>任务之间存在依赖</li><li>需要进度追踪和失败恢复</li></ul><p>典型结构：</p>',18)),(e(),o(p,null,{default:i(()=>[g(l,{id:"mermaid-133",graph:"graph%20TD%0A%20%20A%5B%E7%94%A8%E6%88%B7%E7%9B%AE%E6%A0%87%5D%20--%3E%20B%5BPlanner%20%E7%94%9F%E6%88%90%E6%AD%A5%E9%AA%A4%5D%0A%20%20B%20--%3E%20C%5BExecutor%20%E6%89%A7%E8%A1%8C%E6%AD%A5%E9%AA%A4%5D%0A%20%20C%20--%3E%20D%5B%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%5D%0A%20%20D%20--%3E%20E%5B%E7%BB%93%E6%9E%9C%E8%A7%82%E5%AF%9F%5D%0A%20%20E%20--%3E%20F%7B%E6%98%AF%E5%90%A6%E5%AE%8C%E6%88%90%7D%0A%20%20F%20--%3E%7C%E5%90%A6%7C%20B%0A%20%20F%20--%3E%7C%E6%98%AF%7C%20G%5B%E6%9C%80%E7%BB%88%E5%9B%9E%E7%AD%94%5D%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="_4-workflow-agent-和-autonomous-agent-区别" tabindex="-1">4. Workflow Agent 和 Autonomous Agent 区别？ <a class="header-anchor" href="#_4-workflow-agent-和-autonomous-agent-区别" aria-label="Permalink to “4. Workflow Agent 和 Autonomous Agent 区别？”">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>优点</th><th>风险</th></tr></thead><tbody><tr><td>Workflow Agent</td><td>固定流程，LLM 只处理局部判断</td><td>稳定、可控、易上线</td><td>灵活性较低</td></tr><tr><td>Autonomous Agent</td><td>LLM 自主规划和执行</td><td>灵活、泛化强</td><td>不稳定、成本高、难控</td></tr></tbody></table><p>工程落地通常优先 Workflow Agent，再在关键节点引入 LLM 决策。</p><h2 id="_5-工具调用怎么设计" tabindex="-1">5. 工具调用怎么设计？ <a class="header-anchor" href="#_5-工具调用怎么设计" aria-label="Permalink to “5. 工具调用怎么设计？”">​</a></h2><p>工具设计原则：</p><ul><li>单一职责：一个工具只做一类明确事情。</li><li>Schema 清晰：参数类型、枚举、必填字段要明确。</li><li>幂等优先：避免重复调用产生副作用。</li><li>权限隔离：高危工具必须审批或二次确认。</li><li>可观测：记录工具名、参数、耗时、结果和错误。</li></ul><p>工具执行链路：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LLM 生成 tool_call -&gt; 参数校验 -&gt; 权限判断 -&gt; 执行工具 -&gt; 结果压缩 -&gt; 注入上下文 -&gt; LLM 继续推理</span></span></code></pre></div><h2 id="_6-agent-记忆怎么做" tabindex="-1">6. Agent 记忆怎么做？ <a class="header-anchor" href="#_6-agent-记忆怎么做" aria-label="Permalink to “6. Agent 记忆怎么做？”">​</a></h2><p>常见记忆：</p><ul><li>短期记忆：当前会话上下文。</li><li>长期记忆：用户偏好、历史事实、业务状态。</li><li>工作记忆：当前任务计划、中间结果、待办事项。</li><li>语义记忆：向量库检索出来的相关知识。</li></ul><p>落地建议：</p><ul><li>不要把所有历史都塞进 prompt。</li><li>记忆需要抽取、去重、过期和权限控制。</li><li>重要记忆写入前最好让模型生成结构化摘要，并由规则校验。</li></ul><h2 id="_7-多-agent-是否一定更好" tabindex="-1">7. 多 Agent 是否一定更好？ <a class="header-anchor" href="#_7-多-agent-是否一定更好" aria-label="Permalink to “7. 多 Agent 是否一定更好？”">​</a></h2><p>不一定。多 Agent 适合角色边界清晰、任务可拆分、需要互审的场景。</p><p>常见问题：</p><ul><li>通信成本高。</li><li>责任边界模糊。</li><li>状态同步复杂。</li><li>更难评估和调试。</li></ul><p>面试建议：先说明多 Agent 不是银弹，再给出适用场景，如代码审查、规划执行分离、专家协作、评审仲裁。</p>',18))])}const f=n(h,[["render",A]]);export{m as __pageData,f as default};
